'use strict';
const db = window.supabase.createClient(MEDIRA_CONFIG.url, MEDIRA_CONFIG.key, {
  auth: { storage: window.sessionStorage, persistSession: true, autoRefreshToken: true, detectSessionInUrl: false }
});
const state = { user:null, profile:null, catalogue:[], categories:[], equipment:[], units:[], stock:[], requests:[], items:[], allocations:[], returns:[], returnItems:[], profiles:[], maintenance:[], settings:null, audit:[], loaded:false };
const titles = { dashboard:'Dashboard', pengajuan:'Pengajuan', stok:'Stok alat', pengembalian:'Pengembalian', laporan:'Laporan', grafik:'Grafik', profil:'Profil', setting:'Pengaturan' };
const labels = {diproses:'Diproses',disetujui:'Disetujui',dipinjam:'Dipinjam',selesai:'Selesai',ditolak:'Ditolak',dibatalkan:'Dibatalkan',proses:'Proses',tersedia:'Tersedia',dicadangkan:'Dicadangkan',perawatan:'Perawatan',nonaktif:'Nonaktif',baik:'Baik',rusak_ringan:'Rusak ringan',rusak_berat:'Rusak berat'};
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId = (list,id) => list.find(x=>x.id===id);
const admin = () => state.profile?.role==='admin';
const dateKey = (value=new Date()) => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
const today = () => dateKey();
const fmt = d => d ? new Date(d.length===10?d+'T00:00:00+07:00':d).toLocaleDateString('id-ID',{timeZone:'Asia/Jakarta',day:'2-digit',month:'short',year:'numeric'}) : '—';
const num = v => Number(v||0).toLocaleString('id-ID');
const reqCode = r => 'PJM-'+String(r.request_number).padStart(5,'0');
const badge = s => `<span class="tag ${['diproses','proses','dicadangkan','perawatan','rusak_ringan'].includes(s)?'orange':['ditolak','rusak_berat','terlambat'].includes(s)?'red':['disetujui','dipinjam'].includes(s)?'blue':''}">${esc(labels[s]||s)}</span>`;
const heading = (title,sub,action='') => `<div class="heading"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${action}</div></div>`;
const actionButton = (text,fn,secondary=false) => `<button type="button" class="btn ${secondary?'secondary':''}" onclick="${fn}">${text}</button>`;
const empty = (title='Belum ada data',description='Data akan muncul setelah transaksi pertama dicatat.') => `<div class="empty-state">${icon('pengajuan',30)}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;
const errorMessage = e => e?.code==='23503'?'Data masih dipakai oleh catatan lain. Nonaktifkan data jika tidak digunakan lagi.':e?.code==='23505'?'Data dengan kode/nama tersebut sudah ada.':e?.code==='23514'?'Nilai tidak sesuai aturan. Periksa jumlah, durasi, dan kondisi alat.':e?.message==='Invalid login credentials'?'Email atau kata sandi tidak sesuai.': e?.message||'Koneksi gagal. Silakan coba lagi.';
function toast(message){const n=document.getElementById('announcer'); n.className='toast';n.textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{n.className='';n.textContent='';},5000);}
async function readAll(table){let result=[];for(let offset=0;;offset+=1000){const {data,error}=await db.from(table).select('*').order('id').range(offset,offset+999);if(error)throw error;result.push(...data);if(data.length<1000)return result;}}
async function catalogue(){const {data,error}=await db.rpc('medira_catalogue');if(error)throw error;state.catalogue=data||[];}
let authGeneration=0;
async function loadState(){
  const generation=authGeneration;
  const {data:{user},error}=await db.auth.getUser();if(error||!user)throw new Error('Sesi berakhir. Silakan masuk kembali.');
  const {data:profile,error:pe}=await db.from('profiles').select('*').eq('id',user.id).single();if(pe)throw pe;
  if(!profile.is_active){await db.auth.signOut();throw new Error('Akun dinonaktifkan. Hubungi Admin.');}
  const isAdmin=profile.role==='admin';
  const map={categories:'categories',equipment:'equipment',units:'equipment_units',requests:'loan_requests',items:'loan_items',allocations:'unit_allocations',returns:'returns',returnItems:'return_items',profiles:'profiles'};
  if(isAdmin)Object.assign(map,{maintenance:'maintenance_logs',audit:'audit_logs'});
  const pairs=Object.entries(map);
  const [values,stockResult,preferencesResult]=await Promise.all([
    Promise.all(pairs.map(([,t])=>readAll(t))),db.rpc('medira_stock'),db.rpc('medira_preferences')
  ]);
  if(stockResult.error)throw stockResult.error;if(preferencesResult.error)throw preferencesResult.error;
  if(generation!==authGeneration)throw new Error('Sesi berubah. Silakan muat ulang.');
  state.user=user;state.profile=profile;
  pairs.forEach(([k],i)=>state[k]=values[i]);state.stock=stockResult.data;state.settings=preferencesResult.data;
  if(!isAdmin){state.maintenance=[];state.audit=[];}
  state.requests.sort((a,b)=>b.created_at.localeCompare(a.created_at));state.returns.sort((a,b)=>b.submitted_at.localeCompare(a.submitted_at));
  state.loaded=true;
}
let page='',navVersion=0,booted=false;
const publicPages=['home','tentang','alur','katalog','katalog-semua','login'];
function resetState(){authGeneration++;state.user=null;state.profile=null;state.loaded=false;for(const k of ['requests','items','allocations','returns','returnItems','profiles','maintenance','audit'])state[k]=[];}
async function route(){
  const version=++navVersion;page=location.hash.slice(1)||'home';closeModal();
  if(page==='main-content'){document.getElementById('main-content')?.focus();return;}
  document.title=(titles[page]||'Peminjaman Alat Medis')+' · Medira';
  const isPublic=publicPages.includes(page);document.body.className=isPublic?'public-view':'app-view';
  if(isPublic){
    if(page==='login'&&state.loaded){location.hash='dashboard';return;}
    if(page==='login')document.getElementById('app').innerHTML=loginPage();
    else{
      document.getElementById('app').innerHTML=state.catalogue.length?publicView():`<main class="boot-state"><h1>Medira</h1><p>Memuat inventaris…</p></main>`;
      try{await catalogue();if(version!==navVersion)return;document.getElementById('app').innerHTML=publicView();if(['tentang','alur','katalog'].includes(page))document.getElementById(page)?.scrollIntoView({behavior:'smooth'});}
      catch(e){if(version===navVersion){document.getElementById('app').innerHTML=home()+`<div class="connection-error">Katalog belum dapat dimuat. ${actionButton('Coba lagi','route()',true)}</div>`;toast(errorMessage(e));}}
    }return;
  }
  if(!state.user){sessionStorage.setItem('medira-next',page);location.hash='login';return;}
  document.getElementById('app').innerHTML=shell(`<div class="empty-state" role="status">Memuat data terkini…</div>`);
  try{await loadState();if(version!==navVersion)return;if(['laporan','grafik','setting'].includes(page)&&!admin()){location.hash='dashboard';toast('Halaman ini khusus Admin.');return;}draw();}
  catch(e){if(version!==navVersion)return;document.getElementById('app').innerHTML=shell(`<div class="card error-card"><h2>Data belum dapat dimuat</h2><p>${esc(errorMessage(e))}</p>${actionButton('Coba lagi','route()')}${actionButton('Keluar','logout()',true)}</div>`);}
}
function draw(){const views={dashboard:dashboard,pengajuan:requestsPage,stok:stockPage,pengembalian:returnsPage,laporan:reportsPage,grafik:chartsPage,profil:profilePage,setting:settingsPage};document.getElementById('app').innerHTML=shell((views[page]||dashboard)());window.scrollTo(0,0);}
function publicView(){if(page==='katalog-semua')return `<div class="public-nav-area"><header class="public-nav">${logo()}<a href="#login" class="btn">Masuk ke sistem</a></header></div><main class="home-section" id="main-content">${heading('Katalog alat medis','Ketersediaan dapat berubah saat pengajuan disetujui.')}<label for="public-search">Cari alat medis</label><input id="public-search" class="field" placeholder="Nama alat atau kategori" oninput="filterPublic(this.value)"><div id="public-results" class="public-catalog">${catalogueTiles(state.catalogue)}</div></main>`;return home();}
function artFor(name){const ix=['Patient Monitor','Infusion Pump','Kursi Roda','Konsentrator Oksigen','Tensimeter Digital','Nebulizer'].indexOf(name);return ix>=0?equipmentArt(ix):`<svg viewBox="0 0 150 140" fill="none" stroke="#7894ab" stroke-width="3" aria-hidden="true"><rect x="28" y="42" width="94" height="66" rx="13" fill="#f9fcff"/><path d="M55 42V31h40v11M75 60v30M60 75h30"/></svg>`;}
function catalogueTiles(rows){return rows.length?rows.map((e,i)=>`<a class="catalog-tile" href="#login"><div class="equipment-art">${artFor(e.name)}</div><div class="tile-text"><b>${esc(e.name)}</b><p class="small">${esc(e.category)}</p><small>${e.available} dari ${e.total} unit tersedia</small></div></a>`).join(''):empty('Alat tidak ditemukan','Coba kata kunci lain.');}
function filterPublic(q){document.getElementById('public-results').innerHTML=catalogueTiles(state.catalogue.filter(e=>(e.name+' '+e.category).toLowerCase().includes(q.toLowerCase())));}
function loginPage(){return `<div class="login"><section class="login-side">${logo()}<div><div class="eyebrow" style="color:#c9d9e8">Operasional yang lebih tertata</div><h1>Fokus pada pelayanan.<br>Kami bantu pencatatannya.</h1><p>Satu ruang kerja untuk alat medis dan setiap riwayat peminjamannya.</p></div><small>Medira / Sistem Peminjaman Alat Medis</small></section><section class="login-form"><form id="login-form" onsubmit="signIn(event)"><a href="#home" class="small muted">← Kembali ke beranda</a><h1 style="margin:35px 0 12px">Selamat datang kembali.</h1><p>Masuk menggunakan akun Admin atau Petugas.</p><label for="email">Email</label><input class="field" id="email" name="email" type="email" autocomplete="username" required placeholder="nama@email.com"><label for="password">Kata sandi</label><div class="password-field"><input class="field" id="password" name="password" type="password" autocomplete="current-password" required><button type="button" onclick="togglePassword(this)" aria-label="Tampilkan kata sandi">Lihat</button></div><p class="form-error" role="alert"></p><button class="btn" type="submit">Masuk ke sistem ${icon('arrow')}</button><p class="small muted" style="margin-top:22px">Akun dikelola oleh Admin. Hubungi Admin jika mengalami kendala akses.</p></form></section></div>`;}
function togglePassword(b){const p=b.previousElementSibling;p.type=p.type==='password'?'text':'password';b.textContent=p.type==='password'?'Lihat':'Sembunyikan';b.setAttribute('aria-label',p.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi');}
async function signIn(event){event.preventDefault();const f=event.target;await formTask(f,async()=>{const v=new FormData(f);const {data,error}=await db.auth.signInWithPassword({email:v.get('email').trim(),password:v.get('password')});if(error)throw error;state.user=data.user;await loadState();const next=sessionStorage.getItem('medira-next');sessionStorage.removeItem('medira-next');location.hash=next&&(!['setting','laporan','grafik'].includes(next)||admin())?next:'dashboard';});}
async function logout(){const {error}=await db.auth.signOut({scope:'local'});if(error){toast(errorMessage(error));return;}resetState();location.hash='login';}
function shell(body){const navs=Object.keys(titles).filter(n=>admin()||!['laporan','grafik','setting'].includes(n));return `<aside class="sidebar" id="sidebar">${logo()}<div class="navlabel">RUANG KERJA</div>${navs.map(n=>`<a href="#${n}" class="navitem ${page===n?'active':''}" ${page===n?'aria-current="page"':''}>${icon(n)}${titles[n]}${n==='pengajuan'?`<span class="count">${state.requests.filter(r=>r.status==='diproses'&&!r.deleted_at).length}</span>`:''}</a>`).join('')}<div class="sidebar-bottom"><div class="help"><b class="small">${admin()?'Administrator':'Petugas'}</b><p>${admin()?'Kelola unit, persetujuan, dan pemeriksaan alat.':'Ajukan kebutuhan dan pantau peminjaman Anda.'}</p></div><button class="navitem" onclick="logout()">${icon('logout')}Keluar</button></div></aside><div class="sidebar-scrim" onclick="document.getElementById('sidebar').classList.remove('open')"></div><div class="main"><header class="topbar"><button class="mobile-menu" aria-label="Buka navigasi" onclick="document.getElementById('sidebar').classList.toggle('open')">${icon('menu')}</button><span class="small muted desktop-only">${esc(state.settings?.organization_name||'Medira')} · Inventaris & peminjaman</span><div class="topbar-right"><span class="chip">${fmt(today())}</span><button aria-label="Muat ulang data" title="Muat ulang data" onclick="route()">${icon('pengembalian')}</button><a href="#profil" class="profile-link"><span class="avatar">${esc((state.profile?.full_name||'M').split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><span class="small"><b>${esc(state.profile?.full_name||'Medira')}</b><br><span class="muted">${admin()?'Admin':'Petugas'}</span></span></a></div></header><main class="content" id="main-content" tabindex="-1">${body}</main></div>`;}
function statsFor(id){const s=state.stock.filter(u=>u.equipment_id===id);return {total:s.length,free:s.filter(u=>u.status==='tersedia').length,reserved:s.filter(u=>u.status==='dicadangkan').length,used:s.filter(u=>u.status==='dipinjam').length,service:s.filter(u=>u.status==='perawatan').length};}
function liveRequests(){return state.requests.filter(r=>!r.deleted_at);}
function dashboard(){const total=state.stock.length,free=state.stock.filter(u=>u.status==='tersedia').length,used=state.stock.filter(u=>u.status==='dipinjam').length,service=state.stock.filter(u=>u.status==='perawatan').length,pending=liveRequests().filter(r=>r.status==='diproses').length,late=liveRequests().filter(r=>r.status==='dipinjam'&&r.due_date<today()).length,pct=total?Math.round(free/total*100):0;return heading('Halo, '+(state.profile.full_name.split(' ')[0]||'Petugas')+'.','Ringkasan inventaris dan '+(admin()?'seluruh peminjaman.':'peminjaman Anda.'),actionButton(icon('plus',15)+' Buat pengajuan','requestForm()'))+`<div class="dashboard-top"><section class="card overview"><div class="overview-title">Ringkasan inventaris ${icon('stok',20)}</div><div class="overview-values"><div><strong>${num(total)}</strong><span>Unit alat<br>terdata</span></div><div><strong>${pending}</strong><span>Pengajuan<br>diproses</span></div></div><div class="mini-stats">${[[free,'Tersedia','stok'],[used,'Dipinjam','pengembalian'],[service,'Perawatan','setting']].map(([n,l,i])=>`<div>${icon(i,18)}<strong>${num(n)}</strong><small>${l}</small></div>`).join('')}</div></section>${monthlyChart()}<section class="card availability"><h2>Kesiapan alat</h2><p>${free} dari ${total} unit tersedia</p><div class="donut" style="--pct:${pct}%"><div class="donut-label"><b>${pct}%</b><small>tersedia</small></div></div><a href="#stok" class="btn secondary">Lihat stok ${icon('arrow',14)}</a></section></div><div class="dashboard-middle"><section class="card inventory-mini"><h2>Ketersediaan utama</h2>${state.equipment.slice(0,5).map(e=>`<div class="inventory-check"><span>${esc(e.name)}</span><b>${statsFor(e.id).free} / ${statsFor(e.id).total}</b></div>`).join('')}</section><section class="activity-area"><div class="section-heading"><h2>Perlu ditindaklanjuti</h2></div><div class="task-cards"><article class="task-card">${icon('pengajuan',25)}${badge('diproses')}<h3>${pending} pengajuan<br>${admin()?'perlu ditinjau':'menunggu keputusan'}</h3><a href="#pengajuan" class="textlink">Lihat pengajuan →</a></article><article class="task-card">${icon('pengembalian',25)}<h3>${late} peminjaman<br>melewati jatuh tempo</h3><a href="#pengembalian" class="textlink">Cek pengembalian →</a></article><button class="add-task" onclick="requestForm()">${icon('plus',25)}<span>Pengajuan baru</span></button></div></section></div>${deadlineNotice()}<div class="card"><div class="card-head"><h2>Peminjaman terbaru</h2><a href="#pengajuan" class="textlink">Lihat semua →</a></div>${requestsTable(liveRequests().slice(0,5))}</div>`;}
function deadlineNotice(){const lead=state.settings?.reminder_days??2;const until=new Date(today()+'T00:00:00Z');until.setUTCDate(until.getUTCDate()+lead);const rows=liveRequests().filter(r=>r.status==='dipinjam'&&r.due_date<=until.toISOString().slice(0,10));return rows.length?`<div class="notice" style="margin:0 0 22px">${rows.length} peminjaman sudah atau akan jatuh tempo dalam ${lead} hari. <a href="#pengembalian" class="textlink">Periksa pengembalian →</a></div>`:'';}
function monthlyChart(){const end=new Date(today()+'T00:00:00Z');const months=Array.from({length:6},(_,i)=>{const d=new Date(Date.UTC(end.getUTCFullYear(),end.getUTCMonth()-5+i,1));const key=d.toISOString().slice(0,7);return {label:d.toLocaleDateString('id-ID',{month:'short',year:'2-digit'}),count:state.requests.filter(r=>dateKey(r.created_at).slice(0,7)===key).length};});const max=Math.max(...months.map(m=>m.count),1);return `<section class="card trend-card"><div class="card-head"><div><h2>Aktivitas peminjaman</h2><p>${admin()?'Seluruh pengajuan':'Pengajuan Anda'} · 6 bulan terakhir</p></div></div><div class="column-chart" role="img" aria-label="${esc(months.map(m=>m.label+': '+m.count+' pengajuan').join(', '))}">${months.map(m=>`<div class="chart-column"><b>${m.count}</b><div class="chart-track"><i style="height:${m.count/max*100}%"></i></div><small>${m.label}</small></div>`).join('')}</div>${months.every(m=>!m.count)?'<p class="chart-note">Belum ada pengajuan pada periode ini.</p>':''}</section>`;}
function requestsTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Pengajuan</th><th>Peminjam</th><th>Alat / jumlah</th><th>Jatuh tempo</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(r=>{const p=byId(state.profiles,r.borrower_id);const items=state.items.filter(i=>i.request_id===r.id);return `<tr><td><b>${reqCode(r)}</b><small>${fmt(r.created_at)}</small></td><td><b>${esc(p?.full_name||'Pengguna')}</b><small>${esc(p?.department||'—')}</small></td><td class="wrap-cell">${items.map(i=>`${esc(byId(state.equipment,i.equipment_id)?.name)} <strong>× ${i.quantity}</strong>`).join('<br>')}</td><td>${fmt(r.due_date)}${r.status==='dipinjam'&&r.due_date<today()?'<br>'+badge('terlambat'):''}</td><td>${badge(r.status)}</td><td><button class="textlink" onclick="requestDetail('${r.id}')">Lihat detail</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('Belum ada pengajuan','Buat pengajuan pertama dengan memilih jenis dan jumlah alat.');}
function requestsPage(){return heading('Pengajuan peminjaman',admin()?'Tinjau kebutuhan, alokasikan unit, dan catat penyerahan.':'Ajukan alat dan pantau status peminjaman Anda.',actionButton(icon('plus',15)+' Buat pengajuan','requestForm()'))+`<section class="card"><div class="card-head"><h2>Daftar pengajuan</h2></div><div class="toolbar"><input class="field" id="request-search" aria-label="Cari pengajuan" placeholder="Nomor, peminjam, atau alat" oninput="filterRequests()"><select id="request-status" aria-label="Filter status" onchange="filterRequests()"><option value="">Semua status</option>${['diproses','disetujui','dipinjam','selesai','ditolak','dibatalkan'].map(s=>`<option value="${s}">${labels[s]}</option>`).join('')}</select></div><div id="request-results">${requestsTable(liveRequests())}</div></section>`;}
function filterRequests(){const q=document.getElementById('request-search').value.toLowerCase(),s=document.getElementById('request-status').value;document.getElementById('request-results').innerHTML=requestsTable(liveRequests().filter(r=>(!s||r.status===s)&&searchRequest(r,q)));}
function searchRequest(r,q){return [reqCode(r),byId(state.profiles,r.borrower_id)?.full_name,r.purpose,...state.items.filter(i=>i.request_id===r.id).map(i=>byId(state.equipment,i.equipment_id)?.name)].join(' ').toLowerCase().includes(q);}
function stockPage(){return heading('Stok alat medis','Ketersediaan dihitung dari kondisi dan peminjaman setiap unit.',admin()?actionButton('Tambah jenis alat','equipmentForm()'):'')+`<section class="card"><div class="card-head"><h2>${state.equipment.length} jenis · ${state.stock.length} unit</h2>${admin()?actionButton('Ekspor CSV',"exportCSV('stock')",true):''}</div><div class="toolbar"><input class="field" id="stock-search" aria-label="Cari alat" placeholder="Nama atau kode unit" oninput="filterStock()"><select id="stock-category" aria-label="Filter kategori" onchange="filterStock()"><option value="">Semua kategori</option>${state.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div id="stock-results">${stockTable(state.equipment)}</div></section>`;}
function stockTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Alat medis</th><th>Kategori</th><th>Total</th><th>Tersedia</th><th>Dicadangkan</th><th>Dipinjam</th><th>Perawatan</th><th>Aksi</th></tr></thead><tbody>${rows.map(e=>{const s=statsFor(e.id);return `<tr><td><b>${esc(e.name)}</b><small>${esc([e.brand,e.model].filter(Boolean).join(' · '))}</small>${!e.is_active?badge('nonaktif'):''}</td><td>${esc(byId(state.categories,e.category_id)?.name)}</td><td>${s.total}</td><td>${s.free}</td><td>${s.reserved}</td><td>${s.used}</td><td>${s.service}</td><td><button class="textlink" onclick="equipmentDetail('${e.id}')">Lihat unit</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('Alat tidak ditemukan','Coba kategori atau kata kunci lain.');}
function filterStock(){const q=document.getElementById('stock-search').value.toLowerCase(),c=document.getElementById('stock-category').value;document.getElementById('stock-results').innerHTML=stockTable(state.equipment.filter(e=>(!c||e.category_id===c)&&(e.name.toLowerCase().includes(q)||state.units.some(u=>u.equipment_id===e.id&&u.asset_code.toLowerCase().includes(q)))));}
function returnsPage(){const active=liveRequests().filter(r=>r.status==='dipinjam');return heading('Pengembalian alat',admin()?'Periksa kondisi setiap unit sebelum menyelesaikan pengembalian.':'Laporkan kondisi seluruh unit; stok diperbarui setelah pemeriksaan Admin.')+deadlineNotice()+`<section class="card section-gap"><div class="card-head"><h2>Peminjaman aktif</h2></div>${requestsTable(active)}</section><section class="card"><div class="card-head"><h2>Riwayat pengembalian</h2></div>${state.returns.length?`<div class="table-wrap"><table><thead><tr><th>Pengajuan</th><th>Peminjam</th><th>Diajukan</th><th>Diperiksa</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${state.returns.map(rt=>{const r=byId(state.requests,rt.request_id);return `<tr><td>${r?reqCode(r):'—'}</td><td>${esc(byId(state.profiles,r?.borrower_id)?.full_name)}</td><td>${fmt(rt.submitted_at)}</td><td>${fmt(rt.confirmed_at)}</td><td>${badge(rt.status)}</td><td><button class="textlink" onclick="returnDetail('${rt.id}')">Lihat detail</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('Belum ada pengembalian','Buka detail peminjaman aktif untuk mengajukan pengembalian.')}</section>`;}
function reportsPage(){const first=today().slice(0,7)+'-01';return heading('Laporan peminjaman','Rekap berdasarkan tanggal pengajuan. Ekspor data sesuai filter.',actionButton('Unduh CSV',"exportCSV('loans')"))+`<section class="card"><div class="card-head"><h2>Periode laporan</h2><button class="textlink" onclick="window.print()">Cetak / simpan PDF</button></div><div class="toolbar"><div><label for="report-from">Dari tanggal</label><input id="report-from" type="date" value="${first}" onchange="filterReport()"></div><div><label for="report-to">Sampai tanggal</label><input id="report-to" type="date" value="${today()}" onchange="filterReport()"></div><div><label for="report-status">Status</label><select id="report-status" onchange="filterReport()"><option value="">Semua status</option>${Object.keys(labels).filter(s=>['diproses','disetujui','dipinjam','selesai','ditolak','dibatalkan'].includes(s)).map(s=>`<option value="${s}">${labels[s]}</option>`).join('')}</select></div></div><div id="report-results">${reportContent(state.requests.filter(r=>dateKey(r.created_at)>=first&&dateKey(r.created_at)<=today()))}</div></section>`;}
function reportRows(){const from=document.getElementById('report-from').value,to=document.getElementById('report-to').value,s=document.getElementById('report-status').value;if(from&&to&&from>to)throw new Error('Tanggal awal tidak boleh melewati tanggal akhir.');return state.requests.filter(r=>(!from||dateKey(r.created_at)>=from)&&(!to||dateKey(r.created_at)<=to)&&(!s||r.status===s));}
function reportContent(rows){return `<div class="report-stats"><div><b>${rows.length}</b><span>Pengajuan</span></div><div><b>${state.items.filter(i=>rows.some(r=>r.id===i.request_id)).reduce((s,i)=>s+i.quantity,0)}</b><span>Unit diajukan</span></div><div><b>${rows.filter(r=>r.status==='selesai').length}</b><span>Selesai</span></div></div>${requestsTable(rows)}`;}
function filterReport(){try{document.getElementById('report-results').innerHTML=reportContent(reportRows());}catch(e){document.getElementById('report-results').innerHTML=`<p class="form-error pad">${esc(e.message)}</p>`;}}
function chartsPage(){const categories=state.categories.map(c=>({name:c.name,count:state.units.filter(u=>state.equipment.some(e=>e.id===u.equipment_id&&e.category_id===c.id)).length}));const max=Math.max(...categories.map(c=>c.count),1);return heading('Grafik & analisis','Ringkasan dihitung dari transaksi dan unit yang tercatat.')+`<div class="grid">${monthlyChart()}<section class="card"><div class="card-head"><h2>Distribusi inventaris</h2></div>${categories.map(c=>`<div class="stock-item"><div class="stock-row"><span>${esc(c.name)}</span><b>${c.count} unit</b></div><div class="bar"><i style="width:${c.count/max*100}%"></i></div></div>`).join('')}</section></div><section class="card"><div class="card-head"><h2>Status pengajuan</h2></div><div class="status-grid">${['diproses','disetujui','dipinjam','selesai','ditolak','dibatalkan'].map(s=>`<div>${badge(s)}<strong>${state.requests.filter(r=>r.status===s).length}</strong></div>`).join('')}</div></section>`;}
function profilePage(){const p=state.profile;return heading('Profil saya','Perbarui identitas dan informasi unit kerja Anda.')+`<form class="card formcard section-gap" onsubmit="saveProfile(event)"><div class="formgrid">${input('full_name','Nama lengkap',p.full_name,'text',true)}<div><label>Email</label><input class="field" value="${esc(state.user.email)}" disabled><small class="muted">Email akun dikelola melalui Supabase Auth.</small></div>${input('department','Unit kerja',p.department)}${input('phone','Nomor telepon',p.phone,'tel')}<div class="full">${badge(admin()?'Admin':'Petugas')}</div><div class="full form-error" role="alert"></div><div class="full"><button class="btn">Simpan profil</button></div></div></form><form class="card formcard" onsubmit="changePassword(event)"><h2>Ubah kata sandi</h2><p class="small">Gunakan minimal 12 karakter, termasuk huruf dan angka.</p><div class="formgrid">${input('current_password','Kata sandi saat ini','','password',true)}${input('new_password','Kata sandi baru','','password',true)}${input('confirm_password','Ulangi kata sandi baru','','password',true)}<div class="full form-error" role="alert"></div><div class="full"><button class="btn">Ubah kata sandi</button></div></div></form>`;}
function settingsPage(){return heading('Pengaturan','Identitas fasilitas, pengingat, kategori, dan akses pengguna.')+`<form class="card formcard section-gap" onsubmit="saveSettings(event)"><h2>Pengaturan umum</h2><div class="formgrid">${input('organization_name','Nama fasilitas',state.settings.organization_name,'text',true)}${input('reminder_days','Pengingat sebelum jatuh tempo (hari)',state.settings.reminder_days,'number',true,'min="0" max="30"')}<p class="full small muted">Pengingat tampil di dashboard; tidak mengirim email atau WhatsApp.</p><div class="full form-error" role="alert"></div><div class="full"><button class="btn">Simpan pengaturan</button></div></div></form><section class="card section-gap"><div class="card-head"><h2>Kategori alat</h2>${actionButton('Tambah kategori','categoryForm()',true)}</div><div class="table-wrap"><table><thead><tr><th>Kategori</th><th>Jenis alat</th><th>Aksi</th></tr></thead><tbody>${state.categories.map(c=>`<tr><td>${esc(c.name)}</td><td>${state.equipment.filter(e=>e.category_id===c.id).length}</td><td><button class="textlink" onclick="categoryForm('${c.id}')">Ubah</button> · <button class="textlink" onclick="confirmAction('delete_category','${c.id}','Hapus kategori?','Kategori yang sedang dipakai tidak dapat dihapus.')">Hapus</button></td></tr>`).join('')}</tbody></table></div></section><section class="card section-gap"><div class="card-head"><h2>Akses pengguna</h2></div><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Unit kerja</th><th>Peran</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${state.profiles.map(p=>`<tr><td>${esc(p.full_name)}${p.id===state.user.id?' (Anda)':''}</td><td>${esc(p.department||'—')}</td><td>${esc(p.role)}</td><td>${badge(p.is_active?'Aktif':'nonaktif')}</td><td>${p.id!==state.user.id?`<button class="textlink" onclick="userForm('${p.id}')">Atur akses</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><h2>Aktivitas terbaru</h2></div><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aktivitas</th></tr></thead><tbody>${[...state.audit].sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,30).map(a=>`<tr><td>${fmt(a.created_at)}</td><td>${esc(byId(state.profiles,a.actor_id)?.full_name||'Pengelola sistem')}</td><td>${esc(actionLabels[a.action]||a.action.replaceAll('_',' '))}</td></tr>`).join('')}</tbody></table></div></section>`;}
const actionLabels={create_request:'Membuat pengajuan',approve_request:'Menyetujui pengajuan',handover:'Menyerahkan alat',submit_return:'Mengajukan pengembalian',confirm_return:'Memeriksa pengembalian',update_user:'Mengubah akses pengguna',seed_demo_inventory:'Menambahkan inventaris contoh',bootstrap_demo_account:'Membuat akun',update_profile:'Memperbarui profil'};
function input(name,label,value='',type='text',required=false,extra=''){return `<div><label for="f-${name}">${esc(label)}</label><input class="field" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra} ${type==='password'?'autocomplete="new-password"':''}></div>`;}
function options(rows,selected,label='name'){return rows.map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(r[label])}</option>`).join('');}
function formEnd(text='Simpan'){return `<p class="form-error full" role="alert"></p><div class="actions full"><button class="btn" type="submit">${text}</button><button class="btn secondary" type="button" onclick="closeModal()">Batal</button></div>`;}
let modalFocus=null,modalBusy=false;
function modal(title,body,wide=false){modalFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<dialog class="modal ${wide?'wide':''}" id="medira-dialog" aria-labelledby="modal-title"><div class="modal-heading"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="close-modal" aria-label="Tutup dialog" onclick="closeModal()">×</button></div>${body}</dialog>`;const d=document.getElementById('medira-dialog');d.addEventListener('cancel',e=>{e.preventDefault();closeModal();});d.showModal();}
function closeModal(force=false){if(modalBusy&&!force)return;const d=document.getElementById('medira-dialog');if(d)d.close();document.getElementById('overlay').innerHTML='';if(modalFocus?.isConnected)modalFocus.focus();modalFocus=null;}
async function formTask(form,task){if(form.dataset.busy)return;form.dataset.busy='true';const buttons=[...form.querySelectorAll('button')];const submit=form.querySelector('button[type="submit"],button:not([type])');const original=submit?.innerHTML;buttons.forEach(b=>b.disabled=true);if(submit)submit.textContent='Memproses…';const error=form.querySelector('.form-error');if(error)error.textContent='';modalBusy=!!form.closest('dialog');try{await task();}catch(e){if(error&&error.isConnected)error.textContent=errorMessage(e);else toast(errorMessage(e));}finally{modalBusy=false;delete form.dataset.busy;buttons.forEach(b=>b.disabled=false);if(submit)submit.innerHTML=original;}}
async function commit(action,data,message='Perubahan berhasil disimpan.'){const {error}=await db.rpc('medira_action',{p_action:action,p_data:data});if(error)throw error;closeModal(true);try{await loadState();if(publicPages.includes(page))await route();else draw();toast(message);}catch(e){toast('Perubahan tersimpan, tetapi tampilan belum diperbarui. Tekan muat ulang.');}}
function requestForm(id){const r=id?byId(state.requests,id):null;const items=r?state.items.filter(i=>i.request_id===id):[{equipment_id:'',quantity:1}];modal(r?'Ubah pengajuan':'Pengajuan peminjaman',`<form onsubmit="saveRequest(event,'${id||''}')"><p class="small">Pilih jenis dan jumlah alat. Admin menentukan kode unit saat menyetujui. Jatuh tempo dihitung dari tanggal persetujuan.</p><div class="formgrid">${admin()?`<div class="full"><label for="borrower">Peminjam</label><select id="borrower" name="borrower_id" ${r?'disabled':''}>${options(state.profiles.filter(p=>p.is_active),r?.borrower_id||state.user.id,'full_name')}</select></div>`:''}${input('duration_days','Durasi (hari)',r?.duration_days||3,'number',true,'min="1" max="365"')}<div class="full"><label for="purpose">Keperluan</label><textarea id="purpose" name="purpose" rows="3" maxlength="2000" required>${esc(r?.purpose||'')}</textarea></div><div class="full"><label>Daftar alat</label><div id="request-items">${items.map(i=>requestItem(i)).join('')}</div><button type="button" class="textlink add-line" onclick="addRequestItem()">+ Tambah jenis alat</button></div>${formEnd(r?'Simpan perubahan':'Kirim pengajuan')}</div></form>`,true);}
function requestItem(i={}){return `<div class="request-line"><select class="item-equipment" aria-label="Jenis alat" required><option value="">Pilih alat medis</option>${state.equipment.filter(e=>e.is_active||e.id===i.equipment_id).map(e=>`<option value="${e.id}" ${i.equipment_id===e.id?'selected':''}>${esc(e.name)} — ${statsFor(e.id).free} tersedia</option>`).join('')}</select><input class="field item-quantity" type="number" min="1" max="1000" value="${i.quantity||1}" aria-label="Jumlah unit" required><button type="button" aria-label="Hapus baris alat" onclick="removeRequestItem(this)">×</button></div>`;}
function addRequestItem(){document.getElementById('request-items').insertAdjacentHTML('beforeend',requestItem());}
function removeRequestItem(b){if(document.querySelectorAll('.request-line').length>1)b.closest('.request-line').remove();else toast('Minimal satu jenis alat diperlukan.');}
async function saveRequest(event,id){event.preventDefault();const form=event.target;await formTask(form,async()=>{const v=Object.fromEntries(new FormData(form));v.duration_days=Number(v.duration_days);v.purpose=v.purpose.trim();v.items=[...form.querySelectorAll('.request-line')].map(el=>({equipment_id:el.querySelector('select').value,quantity:Number(el.querySelector('input').value)}));if(new Set(v.items.map(i=>i.equipment_id)).size!==v.items.length)throw new Error('Jenis alat yang sama cukup ditulis dalam satu baris.');if(id)v.id=id;await commit(id?'edit_request':'create_request',v,'Pengajuan berhasil disimpan.');});}
function requestDetail(id){const r=byId(state.requests,id);if(!r)return;const p=byId(state.profiles,r.borrower_id),items=state.items.filter(i=>i.request_id===id),allocs=state.allocations.filter(a=>items.some(i=>i.id===a.loan_item_id));const rt=state.returns.find(x=>x.request_id===id&&x.status==='proses');let actions='';if(r.status==='diproses'){actions+=actionButton('Ubah',`requestForm('${id}')`,true);if(admin())actions+=actionButton('Setujui & pilih unit',`approvalForm('${id}')`)+actionButton('Tolak',`confirmAction('reject_request','${id}','Tolak pengajuan?','Tuliskan alasan penolakan.',true)`,true);}
 if(r.status==='disetujui'&&admin())actions+=actionButton('Catat penyerahan',`confirmAction('handover','${id}','Konfirmasi penyerahan alat','Lanjutkan hanya setelah seluruh unit diserahkan kepada peminjam.')`);
 if(r.status==='diproses'||(r.status==='disetujui'&&admin()))actions+=actionButton('Batalkan',`confirmAction('cancel_request','${id}','Batalkan pengajuan?','Unit yang dicadangkan akan tersedia kembali.')`,true);
 if((r.status==='diproses'||admin()&&['disetujui','ditolak','dibatalkan'].includes(r.status))&&!r.deleted_at)actions+=actionButton('Hapus',`confirmAction('delete_request','${id}','Hapus dari daftar pengajuan?','Catatan tetap disimpan untuk riwayat dan audit.')`,true);
 if(r.status==='dipinjam')actions+=rt?actionButton('Lihat pengembalian',`returnDetail('${rt.id}')`):actionButton('Ajukan pengembalian',`returnForm('${id}')`);
 modal(reqCode(r),`${badge(r.status)}<dl class="detail-grid"><div><dt>Peminjam</dt><dd>${esc(p?.full_name)}</dd></div><div><dt>Unit kerja</dt><dd>${esc(p?.department||'—')}</dd></div><div><dt>Diajukan</dt><dd>${fmt(r.created_at)}</dd></div><div><dt>Durasi</dt><dd>${r.duration_days} hari</dd></div><div><dt>Disetujui</dt><dd>${fmt(r.approved_at)}</dd></div><div><dt>Jatuh tempo</dt><dd>${fmt(r.due_date)}</dd></div><div><dt>Diserahkan</dt><dd>${fmt(r.handed_over_at)}</dd></div><div><dt>Ditutup</dt><dd>${fmt(r.closed_at)}</dd></div></dl><h3 class="small">Keperluan</h3><p class="prewrap">${esc(r.purpose)}</p>${r.decision_note?`<p class="notice prewrap">${esc(r.decision_note)}</p>`:''}<div class="summary-lines">${items.map(i=>`<div><b>${esc(byId(state.equipment,i.equipment_id)?.name)}</b><span>${i.quantity} unit</span></div>`).join('')}</div>${allocs.length?`<h3 class="small">Unit yang dialokasikan</h3><div class="unit-pills">${allocs.map(a=>`<span class="chip">${esc(byId(state.units,a.unit_id)?.asset_code)}${a.release_reason?' · '+esc(labels[a.release_reason]||a.release_reason):''}</span>`).join('')}</div>`:''}<div class="actions modal-actions">${actions}</div>`,true);}
function approvalForm(id){const r=byId(state.requests,id);modal('Pilih unit untuk '+reqCode(r),`<form onsubmit="approveRequest(event,'${id}')"><p class="small">Centang tepat sejumlah unit yang diajukan. Persetujuan mencadangkan unit; penyerahan dicatat terpisah.</p>${state.items.filter(i=>i.request_id===id).map(i=>{const available=state.stock.filter(u=>u.equipment_id===i.equipment_id&&u.status==='tersedia');return `<fieldset class="unit-selection" data-equipment="${i.equipment_id}" data-quantity="${i.quantity}"><legend>${esc(byId(state.equipment,i.equipment_id)?.name)} · pilih ${i.quantity} unit</legend>${available.length?available.map(u=>`<label class="checkbox-row"><input type="checkbox" name="unit_ids" value="${u.unit_id}"><span>${esc(u.asset_code)}</span>${badge('baik')}</label>`).join(''):'<p class="form-error">Tidak ada unit tersedia.</p>'}</fieldset>`;}).join('')}<label for="approval-note">Catatan (opsional)</label><textarea id="approval-note" name="note" rows="2"></textarea>${formEnd('Setujui & cadangkan unit')}</form>`,true);}
async function approveRequest(event,id){event.preventDefault();await formTask(event.target,async()=>{for(const field of event.target.querySelectorAll('fieldset'))if(field.querySelectorAll('input:checked').length!==Number(field.dataset.quantity))throw new Error('Jumlah unit yang dipilih harus sesuai pada setiap jenis alat.');const f=new FormData(event.target);await commit('approve_request',{id,unit_ids:f.getAll('unit_ids'),note:f.get('note')},'Pengajuan disetujui. Unit dicadangkan hingga diserahkan.');});}
function confirmAction(action,id,title,description,requireNote=false){modal(title,`<form onsubmit="runConfirmation(event,'${action}','${id}')"><p>${esc(description)}</p><label for="confirm-note">Catatan${requireNote?' (wajib)':' (opsional)'}</label><textarea name="note" id="confirm-note" rows="3" ${requireNote?'required':''}></textarea>${formEnd('Konfirmasi')}</form>`);}
async function runConfirmation(e,action,id){e.preventDefault();await formTask(e.target,async()=>commit(action,{id,note:new FormData(e.target).get('note')}));}
function loanAllocations(requestId){return state.allocations.filter(a=>a.released_at===null&&state.items.some(i=>i.id===a.loan_item_id&&i.request_id===requestId));}
function conditionOptions(selected){return ['baik','rusak_ringan','rusak_berat'].map(c=>`<option value="${c}" ${selected===c?'selected':''}>${labels[c]}</option>`).join('');}
function returnForm(requestId,returnId,confirm=false){const r=byId(state.requests,requestId);const rt=byId(state.returns,returnId);const rows=loanAllocations(requestId);modal(confirm?'Pemeriksaan pengembalian':'Kondisi pengembalian',`<form onsubmit="saveReturn(event,'${requestId}','${returnId||''}',${confirm})"><p class="small">${reqCode(r)} · Seluruh unit dikembalikan bersama. ${confirm?'Unit rusak akan masuk perawatan.':'Admin akan memeriksa kondisi sebelum memperbarui stok.'}</p><div class="return-lines">${rows.map(a=>{const u=byId(state.units,a.unit_id),e=byId(state.equipment,u?.equipment_id),ri=state.returnItems.find(i=>i.return_id===returnId&&i.allocation_id===a.id);return `<fieldset class="return-line" data-allocation="${a.id}"><legend>${esc(u?.asset_code)} · ${esc(e?.name)}</legend>${confirm?`<p class="small">Dilaporkan: ${esc(labels[ri?.reported_condition])} ${ri?.notes?'· '+esc(ri.notes):''}</p>`:''}<label>Kondisi ${confirm?'hasil pemeriksaan':'yang dilaporkan'}</label><select name="condition" required>${conditionOptions(ri?.reported_condition||'baik')}</select>${confirm?'':`<label>Catatan kondisi</label><input class="field" name="notes" value="${esc(ri?.notes||'')}" placeholder="Catatan kerusakan jika ada">`}</fieldset>`;}).join('')}</div>${confirm?'':`<label for="return-notes">Catatan pengembalian</label><textarea name="return_notes" id="return-notes" rows="2">${esc(rt?.notes||'')}</textarea>`}${formEnd(confirm?'Konfirmasi pemeriksaan':'Kirim pengembalian')}</form>`,true);}
async function saveReturn(event,requestId,returnId,confirm){event.preventDefault();await formTask(event.target,async()=>{const items=[...event.target.querySelectorAll('.return-line')].map(el=>({allocation_id:el.dataset.allocation,condition:el.querySelector('select').value,notes:el.querySelector('input')?.value||''}));const payload={items,notes:new FormData(event.target).get('return_notes')||''};if(returnId)payload.id=returnId;else payload.request_id=requestId;await commit(confirm?'confirm_return':returnId?'edit_return':'submit_return',payload,confirm?'Pemeriksaan selesai. Stok dan kondisi unit diperbarui.':'Pengembalian menunggu pemeriksaan Admin.');});}
function returnDetail(id){const rt=byId(state.returns,id);if(!rt)return;const r=byId(state.requests,rt.request_id);const rows=state.returnItems.filter(i=>i.return_id===id);modal('Pengembalian '+reqCode(r),`${badge(rt.status)}<p class="small">Diajukan ${fmt(rt.submitted_at)} · Diperiksa ${fmt(rt.confirmed_at)}</p><div class="table-wrap"><table><thead><tr><th>Unit</th><th>Dilaporkan</th><th>Hasil pemeriksaan</th></tr></thead><tbody>${rows.map(ri=>{const a=byId(state.allocations,ri.allocation_id),u=byId(state.units,a?.unit_id);return `<tr><td><b>${esc(u?.asset_code)}</b><small>${esc(ri.notes)}</small></td><td>${badge(ri.reported_condition)}</td><td>${ri.verified_condition?badge(ri.verified_condition):'Menunggu'}</td></tr>`;}).join('')}</tbody></table></div><p class="prewrap">${esc(rt.notes)}</p><div class="actions">${rt.status==='proses'?`${admin()?actionButton('Periksa & konfirmasi',`returnForm('${r.id}','${id}',true)`):''}${actionButton('Ubah laporan kondisi',`returnForm('${r.id}','${id}')`,true)}${actionButton('Batalkan pengembalian',`confirmAction('cancel_return','${id}','Batalkan pengembalian?','Peminjaman tetap aktif dan unit belum tersedia kembali.')`,true)}`:''}</div>`,true);}
function equipmentDetail(id){const e=byId(state.equipment,id);const units=state.units.filter(u=>u.equipment_id===id).sort((a,b)=>a.asset_code.localeCompare(b.asset_code));modal(e.name,`<p class="small">${esc(byId(state.categories,e.category_id)?.name)} · ${esc([e.brand,e.model].filter(Boolean).join(' / ')||'Merek/model belum diisi')}</p>${e.description?`<p class="small prewrap">${esc(e.description)}</p>`:''}${admin()?`<div class="actions section-gap">${actionButton('Tambah unit',`unitForm('${id}')`)}${actionButton('Ubah jenis alat',`equipmentForm('${id}')`,true)}${actionButton('Hapus jenis',`confirmAction('delete_equipment','${id}','Hapus jenis alat?','Hanya jenis alat tanpa unit dan riwayat pengajuan yang dapat dihapus.')`,true)}</div>`:''}<div class="table-wrap"><table><thead><tr><th>Kode unit</th><th>Lokasi</th><th>Kondisi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${units.map(u=>`<tr><td><b>${esc(u.asset_code)}</b><small>${esc(u.serial_number||'Tanpa nomor seri')}</small></td><td>${esc(u.location||'—')}</td><td>${badge(u.condition)}</td><td>${badge(state.stock.find(s=>s.unit_id===u.id)?.status)}</td><td><button class="textlink" onclick="unitDetail('${u.id}')">Detail</button></td></tr>`).join('')}</tbody></table></div>${!units.length?empty('Belum ada unit','Tambahkan unit fisik untuk jenis alat ini.'):''}`,true);}
function unitDetail(id){const u=byId(state.units,id),e=byId(state.equipment,u.equipment_id),status=state.stock.find(s=>s.unit_id===id)?.status;const history=state.allocations.filter(a=>a.unit_id===id).sort((a,b)=>b.allocated_at.localeCompare(a.allocated_at));modal(u.asset_code,`<p>${esc(e.name)}</p>${badge(status)} ${badge(u.condition)}<dl class="detail-grid"><div><dt>Nomor seri</dt><dd>${esc(u.serial_number||'—')}</dd></div><div><dt>Lokasi</dt><dd>${esc(u.location||'—')}</dd></div></dl><p class="small prewrap">${esc(u.notes)}</p>${admin()?`<div class="actions section-gap">${actionButton('Ubah data unit',`unitForm('${e.id}','${id}')`,true)}${status==='tersedia'?actionButton('Masukkan perawatan',`maintenanceForm('${id}')`,true):''}${status==='perawatan'?actionButton('Selesai diperbaiki',`confirmAction('finish_maintenance','${id}','Nyatakan unit siap digunakan','Lanjutkan hanya setelah perbaikan selesai dan unit dinyatakan layak.',true)`):''}${['tersedia','perawatan'].includes(status)?actionButton('Nonaktifkan',`confirmAction('retire_unit','${id}','Nonaktifkan unit?','Unit tidak akan tersedia untuk peminjaman berikutnya.',true)`,true):''}${actionButton('Hapus unit',`confirmAction('delete_unit','${id}','Hapus unit?','Unit yang sudah memiliki riwayat tidak dapat dihapus.')`,true)}</div>`:''}<h3 class="small">${admin()?'Riwayat peminjaman unit':'Riwayat peminjaman Anda untuk unit ini'}</h3>${history.length?`<div class="summary-lines">${history.map(a=>{const i=byId(state.items,a.loan_item_id),r=byId(state.requests,i?.request_id);return `<div><span>${r?reqCode(r):'—'} · ${fmt(a.allocated_at)}</span><span>${a.released_at?'Ditutup '+fmt(a.released_at):'Aktif'}</span></div>`;}).join('')}</div>`:'<p class="small muted">Belum ada riwayat yang dapat ditampilkan.</p>'}${admin()?`<h3 class="small">Riwayat perawatan</h3>${state.maintenance.filter(m=>m.unit_id===id).map(m=>`<p class="small">${fmt(m.opened_at)} · ${m.resolved_at?'Selesai '+fmt(m.resolved_at):'Dalam perawatan'}<br>${esc(m.resolution_note||m.notes)}</p>`).join('')||'<p class="small muted">Belum ada perawatan.</p>'}`:''}`,true);}
function equipmentForm(id){const e=byId(state.equipment,id)||{};modal(id?'Ubah jenis alat':'Tambah jenis alat',`<form onsubmit="saveEquipment(event,'${id||''}')"><div class="formgrid">${input('name','Nama alat',e.name||'','text',true,'maxlength="150"')}<div><label for="equipment-category">Kategori</label><select name="category_id" id="equipment-category" required><option value="">Pilih kategori</option>${options(state.categories,e.category_id)}</select></div>${input('brand','Merek',e.brand||'')}${input('model','Model',e.model||'')}<div class="full"><label for="equipment-description">Deskripsi</label><textarea name="description" id="equipment-description" rows="3">${esc(e.description||'')}</textarea></div>${id?`<div><label for="equipment-active">Status jenis alat</label><select name="is_active" id="equipment-active"><option value="true" ${e.is_active?'selected':''}>Aktif</option><option value="false" ${!e.is_active?'selected':''}>Nonaktif</option></select></div>`:''}${formEnd()}</div></form>`,true);}
async function saveEquipment(e,id){e.preventDefault();await formTask(e.target,async()=>{const v=Object.fromEntries(new FormData(e.target));if(id)v.id=id;if('is_active' in v)v.is_active=v.is_active==='true';await commit('save_equipment',v);});}
function unitForm(equipmentId,id){const u=byId(state.units,id)||{};modal(id?'Ubah data unit':'Tambah unit fisik',`<form onsubmit="saveUnit(event,'${equipmentId}','${id||''}')"><p class="small">${esc(byId(state.equipment,equipmentId)?.name)}${id?'':' · Unit baru dicatat dalam kondisi baik dan siap digunakan.'}</p><div class="formgrid">${input('asset_code','Kode unit',u.asset_code||'','text',true,'maxlength="60"')}${input('serial_number','Nomor seri (opsional)',u.serial_number||'')}${input('location','Lokasi penyimpanan',u.location||'Gudang Alat Medis')}<div class="full"><label for="unit-notes">Catatan</label><textarea name="notes" id="unit-notes" rows="3">${esc(u.notes||'')}</textarea></div>${formEnd()}</div></form>`);}
async function saveUnit(e,equipmentId,id){e.preventDefault();await formTask(e.target,async()=>{const v=Object.fromEntries(new FormData(e.target));v.equipment_id=equipmentId;if(id)v.id=id;await commit('save_unit',v);});}
function maintenanceForm(id){modal('Catat perawatan unit',`<form onsubmit="saveMaintenance(event,'${id}')"><label for="maintenance-condition">Kondisi awal</label><select id="maintenance-condition" name="condition">${conditionOptions('baik')}</select><label for="maintenance-notes">Alasan perawatan</label><textarea id="maintenance-notes" name="notes" required rows="3"></textarea>${formEnd('Mulai perawatan')}</form>`);}
async function saveMaintenance(e,id){e.preventDefault();await formTask(e.target,()=>commit('start_maintenance',{id,...Object.fromEntries(new FormData(e.target))}));}
function categoryForm(id){const c=byId(state.categories,id)||{};modal(id?'Ubah kategori':'Tambah kategori',`<form onsubmit="saveCategory(event,'${id||''}')">${input('name','Nama kategori',c.name||'','text',true,'maxlength="100"')}<label for="category-desc">Deskripsi</label><textarea id="category-desc" name="description" rows="3">${esc(c.description||'')}</textarea>${formEnd()}</form>`);}
async function saveCategory(e,id){e.preventDefault();await formTask(e.target,()=>commit('save_category',{...Object.fromEntries(new FormData(e.target)),...(id?{id}:{})}));}
function userForm(id){const p=byId(state.profiles,id);modal('Akses '+p.full_name,`<form onsubmit="saveUser(event,'${id}')"><label for="user-role">Peran</label><select id="user-role" name="role"><option value="petugas" ${p.role==='petugas'?'selected':''}>Petugas</option><option value="admin" ${p.role==='admin'?'selected':''}>Admin</option></select><label for="user-active">Status akun</label><select id="user-active" name="is_active"><option value="true" ${p.is_active?'selected':''}>Aktif</option><option value="false" ${!p.is_active?'selected':''}>Nonaktif</option></select><p class="small">Admin dapat mengelola semua transaksi dan akses pengguna. Akun nonaktif tidak dapat membaca atau mengubah data operasional.</p>${formEnd('Simpan akses')}</form>`);}
async function saveUser(e,id){e.preventDefault();await formTask(e.target,()=>{const v=Object.fromEntries(new FormData(e.target));return commit('update_user',{id,role:v.role,is_active:v.is_active==='true'});});}
async function saveProfile(e){e.preventDefault();await formTask(e.target,()=>commit('update_profile',Object.fromEntries(new FormData(e.target))));}
async function saveSettings(e){e.preventDefault();await formTask(e.target,()=>{const v=Object.fromEntries(new FormData(e.target));return commit('update_settings',{organization_name:v.organization_name,reminder_days:Number(v.reminder_days)});});}
async function changePassword(e){e.preventDefault();await formTask(e.target,async()=>{const v=Object.fromEntries(new FormData(e.target));if(v.new_password.length<12||!/[a-zA-Z]/.test(v.new_password)||!/[0-9]/.test(v.new_password))throw new Error('Gunakan minimal 12 karakter, termasuk huruf dan angka.');if(v.new_password!==v.confirm_password)throw new Error('Pengulangan kata sandi tidak cocok.');const {error:verifyError}=await db.auth.signInWithPassword({email:state.user.email,password:v.current_password});if(verifyError)throw new Error('Kata sandi saat ini tidak sesuai.');const {error}=await db.auth.updateUser({password:v.new_password});if(error)throw error;e.target.reset();toast('Kata sandi berhasil diubah.');});}
function exportCSV(kind){try{if(!admin())throw new Error('Ekspor hanya untuk Admin.');let rows;if(kind==='stock')rows=[['Kode unit','Nama alat','Kategori','Nomor seri','Lokasi','Kondisi','Status'],...state.units.map(u=>{const e=byId(state.equipment,u.equipment_id);return [u.asset_code,e?.name,byId(state.categories,e?.category_id)?.name,u.serial_number,u.location,labels[u.condition],labels[state.stock.find(s=>s.unit_id===u.id)?.status]];})];else rows=[['No pengajuan','Peminjam','Unit kerja','Tanggal pengajuan','Jatuh tempo','Status','Nama alat','Jumlah'],...reportRows().flatMap(r=>state.items.filter(i=>i.request_id===r.id).map(i=>[reqCode(r),byId(state.profiles,r.borrower_id)?.full_name,byId(state.profiles,r.borrower_id)?.department,fmt(r.created_at),r.due_date,labels[r.status],byId(state.equipment,i.equipment_id)?.name,i.quantity]))];const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='medira-'+(kind==='stock'?'stok':'laporan')+'-'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){toast(errorMessage(e));}}
window.addEventListener('hashchange',()=>{if(booted)route();});
db.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'&&booted){resetState();if(!publicPages.includes(location.hash.slice(1)))location.hash='login';}});
(async function boot(){try{const {data:{session}}=await db.auth.getSession();if(session){state.user=session.user;try{await loadState();}catch(e){resetState();toast(errorMessage(e));}}}catch(e){toast(errorMessage(e));}finally{booted=true;await route();}})();
